import base64, hashlib, struct

tests = {
    "a.css": "CK9avG",
    "b.css": "dyGcAa",
    "test.css": "EgL3uq",
    "foo.css": "v1c59a",
    "a/b.css": "SwpJaW",
    "a/b/c.css": "NMf3RG",
}

def fnv1a_32(s):
    h = 2166136261
    for b in s.encode():
        h ^= b
        h = (h * 16777619) & 0xFFFFFFFF
    return h

def fnv1a_64(s):
    h = 14695981039346656037
    for b in s.encode():
        h ^= b
        h = (h * 1099511628211) & 0xFFFFFFFFFFFFFFFF
    return h

def djb2(s):
    h = 5381
    for c in s:
        h = ((h << 5) + h + ord(c)) & 0xFFFFFFFF
    return h

def sdbm(s):
    h = 0
    for c in s:
        h = (ord(c) + (h << 6) + (h << 16) - h) & 0xFFFFFFFF
    return h

def b64url_int(h, bits=32):
    # encode int as bytes big-endian then base64url?
    b = h.to_bytes(4, 'big')
    return base64.urlsafe_b64encode(b).decode().rstrip("=")

def b64url_le(h):
    b = h.to_bytes(4, 'little')
    return base64.urlsafe_b64encode(b).decode().rstrip("=")

for rel, exp in tests.items():
    print(f"{rel} exp {exp}")
    print(f"  fnv32 BE {b64url_int(fnv1a_32(rel))} LE {b64url_le(fnv1a_32(rel))} hex {fnv1a_32(rel):08x}")
    print(f"  djb2 BE {b64url_int(djb2(rel))} hex {djb2(rel):08x}")
    # try crc?
    import binascii
    crc = binascii.crc32(rel.encode()) & 0xFFFFFFFF
    print(f"  crc BE {b64url_int(crc)} hex {crc:08x}")
    # try md5 first 4 bytes?
    import hashlib
    md5 = hashlib.md5(rel.encode()).digest()
    print(f"  md5-4 BE {base64.urlsafe_b64encode(md5[:4]).decode().rstrip('=')} LE? {base64.urlsafe_b64encode(md5[:4][::-1]).decode().rstrip('=')}")
