import json, base64, hashlib, binascii, zlib, struct
pairs = json.loads(open("/tmp/pairs.json").read())

def b64_be(h):
    return base64.urlsafe_b64encode(h.to_bytes(4,'big')).decode().rstrip("=")
def b64_le(h):
    return base64.urlsafe_b64encode(h.to_bytes(4,'little')).decode().rstrip("=")

def fnv1_32(s, seed=2166136261):
    h=seed
    for b in s.encode():
        h = (h * 16777619) & 0xFFFFFFFF
        h ^= b
    return h
def fnv1a_32(s, seed=2166136261):
    h=seed
    for b in s.encode():
        h ^= b
        h = (h * 16777619) & 0xFFFFFFFF
    return h

def djb2(s):
    h=5381
    for c in s:
        h=((h<<5)+h+ord(c)) & 0xFFFFFFFF
    return h

def djb2a(s): # xor variant?
    h=5381
    for c in s:
        h=((h<<5)+h ^ ord(c)) & 0xFFFFFFFF
    return h

def sdbm(s):
    h=0
    for c in s:
        h=(ord(c)+(h<<6)+(h<<16)-h) & 0xFFFFFFFF
    return h

def jenkins_one_at_a_time(s):
    h=0
    for c in s:
        h+=ord(c)
        h+=(h<<10)
        h^=(h>>6)
        h&=0xFFFFFFFF
    h+=(h<<3)
    h^=(h>>11)
    h+=(h<<15)
    h&=0xFFFFFFFF
    return h

def adler(s):
    return zlib.adler32(s.encode()) & 0xFFFFFFFF

def crc(s):
    return binascii.crc32(s.encode()) & 0xFFFFFFFF

# Try all with BE/LE
funcs = {"fnv1":fnv1_32, "fnv1a":fnv1a_32, "djb2":djb2, "djb2a":djb2a, "sdbm":sdbm, "jenkins":jenkins_one_at_a_time, "adler":adler, "crc":crc}
