    if not ok:
        # print sample for a.css
        h=f("a.css")
        print(f"{name} a.css {h:08x} BE={b64_be(h)} LE={b64_le(h)} exp CK9avG")

# Try with stem?
print("--- stem ---")
for name, f in funcs.items():
    for rel, exp in pairs.items():
        stem=rel.split(".")[0].split("/")[-1]
        h=f(stem)
        if b64_be(h)==exp or b64_le(h)==exp:
            print(f"MATCH STEM {name} {rel} stem {stem} {exp}")

# Try with different seeds for fnv?
print("--- fnv seeds ---")
for seed in [0, 0x811c9dc5, 0x01000193, 0x9747b28c]:
    for rel, exp in pairs.items():
        h=fnv1a_32(rel, seed)
        if b64_be(h)==exp or b64_le(h)==exp:
            print(f"MATCH fnv seed {seed:08x} {rel}")

